int a = 10;
int b = 10;

a == b;   // true

Address a = new Address("서울", "강남대로", "12345");
Address b = new Address("서울", "강남대로", "12345");

a == b;        // false — 다른 인스턴스
a.equals(b);   // false — Object.equals 는 == 과 같다

@Embeddable
public class Address {

    private String city;
    private String street;
    private String zipcode;

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || !(o instanceof Address)) return false;

        Address other = (Address) o;
        return Objects.equals(getCity(), other.getCity())
            && Objects.equals(getStreet(), other.getStreet())
            && Objects.equals(getZipcode(), other.getZipcode());
    }

    @Override
    public int hashCode() {
        return Objects.hash(getCity(), getStreet(), getZipcode());
    }
}

Set<Address> set = new HashSet<>();
set.add(new Address("서울", "강남대로", "12345"));

boolean has = set.contains(
    new Address("서울", "강남대로", "12345"));

System.out.println(has);   // false
